#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long double D;
    cin >> N >> D;

    vector<long double> P(N), C(N);
    for (int i = 0; i < N; ++i) {
        cin >> P[i] >> C[i];
    }

    const long double INF = numeric_limits<long double>::infinity();
    vector<long double> dp(N, INF);
    dp[0] = 0.0L;

    long double ans = INF;

    for (int i = 0; i < N; ++i) {
        if (!isfinite(dp[i])) continue;

        for (int j = i + 1; j < N; ++j) {
            long double dist = P[j] - P[i];
            long double t = dist * dist / C[i];
            dp[j] = min(dp[j], dp[i] + t);
        }

        long double dist = D - P[i];
        long double t = dist * dist / C[i];
        ans = min(ans, dp[i] + t);
    }

    cout << fixed << setprecision(3) << ans << '\n';
    return 0;
}
